package cn.zj.zjmarket.infrastructure.adapter.repository;
import cn.zj.zjmarket.domain.payment.adapter.repository.*;
import cn.zj.zjmarket.domain.payment.model.valobj.*;
import cn.zj.zjmarket.domain.payment.service.impl.PaymentService;
import cn.zj.zjmarket.domain.order.adapter.repository.IOrderRepository;
import cn.zj.zjmarket.domain.order.model.entity.MarketOrder;
import cn.zj.zjmarket.domain.order.model.valobj.ReservationEvidence;
import cn.zj.zjmarket.domain.order.service.impl.OrderService;
import cn.zj.zjmarket.domain.inventory.model.entity.InventoryAccount;
import cn.zj.zjmarket.infrastructure.gateway.mq.TradeMessageReader;
import com.fasterxml.jackson.databind.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import javax.sql.DataSource;
import java.util.*;
import java.nio.charset.StandardCharsets;

/** Each member commits independently; network calls never run under these business locks. */
public final class FulfillmentRepository implements IFulfillmentRepository {
 private final JdbcTemplate db;private final TransactionTemplate tx;private final IOrderRepository orders;private final ISettlementRepository settlement;private final ObjectMapper json=new ObjectMapper();
 public FulfillmentRepository(DataSource ds,TransactionTemplate tx,IOrderRepository orders,ISettlementRepository settlement){db=new JdbcTemplate(ds);this.tx=tx;this.orders=orders;this.settlement=settlement;}
 private static final String NOW="CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)";
 private long now(){return db.queryForObject("SELECT "+NOW,Long.class);}
 private Map<String,Object> first(String sql,Object...a){var x=db.queryForList(sql,a);return x.isEmpty()?null:x.getFirst();}
 private String raw(Map<String,Object> row,String key){return new String((byte[])row.get(key),StandardCharsets.UTF_8);}
 private JsonNode tree(String s){try{return json.readTree(s);}catch(Exception e){throw new IllegalArgumentException("Fulfillment evidence invalid",e);}}
 private String encode(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalStateException("Fulfillment snapshot invalid",e);}}
 private String canonicalHash(Object value){try{var codec=new cn.zj.zjmarket.infrastructure.gateway.codec.ContractCodec();return cn.zj.zjmarket.infrastructure.gateway.codec.ContractCodec.sha256(codec.encode(value));}catch(Exception invalid){throw new IllegalArgumentException("Invalid team cursor",invalid);}}
 private void one(int n){if(n!=1)throw new IllegalStateException("Fulfillment atomic write mismatch");}
 private MarketOrder lock(String id){var l=first("SELECT user_id,goods_id FROM b_market_order WHERE order_id=?",id);if(l==null)return null;String u=l.get("user_id").toString(),g=l.get("goods_id").toString();db.queryForList("SELECT user_id FROM b_user WHERE user_id=? FOR UPDATE",u);db.queryForList("SELECT goods_id FROM b_product WHERE goods_id=? FOR UPDATE",g);db.queryForList("SELECT user_id FROM b_purchase_guard WHERE user_id=? AND goods_id=? FOR UPDATE",u,g);db.queryForList("SELECT goods_id FROM b_inventory_account WHERE goods_id=? FOR UPDATE",g);db.queryForList("SELECT order_id FROM b_market_order WHERE order_id=? FOR UPDATE",id);db.queryForList("SELECT order_id FROM b_inventory_reservation WHERE order_id=? FOR UPDATE",id);db.queryForList("SELECT order_id FROM b_trade_coordination WHERE order_id=? FOR UPDATE",id);db.queryForList("SELECT payment_id FROM b_payment WHERE order_id=? FOR UPDATE",id);db.queryForList("SELECT a.attempt_id FROM b_payment_attempt a JOIN b_payment p ON p.payment_id=a.payment_id WHERE p.order_id=? ORDER BY a.attempt_no FOR UPDATE",id);db.queryForList("SELECT operation_id FROM b_payment_operation WHERE order_id=? ORDER BY created_at_ms,operation_id FOR UPDATE",id);return orders.byId(u,id);}
 private Map<String,Object> cursor(JsonNode e){return first("SELECT * FROM b_team_cursor WHERE source=? AND channel=? AND team_id=? FOR UPDATE",e.path("source").asText(),e.path("channel").asText(),e.path("payload").path("teamId").asText());}
 public List<String> due(int size){return db.queryForList("SELECT work_id FROM b_trade_work WHERE kind='TEAM_COMPLETED' AND state IN ('READY','WAITING_DEPENDENCY','LEASED') AND next_attempt_ms<="+NOW+" AND (lease_until_ms IS NULL OR lease_until_ms<="+NOW+") ORDER BY next_attempt_ms,work_id LIMIT ?",String.class,size);}
 private void waitFor(Map<String,Object> w,long n){db.update("UPDATE b_trade_work SET state='WAITING_DEPENDENCY',next_attempt_ms=?,lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE work_id=?",n+3000,n,w.get("work_id"));}
 private boolean ready(MarketOrder o,Map<String,Object> p){return o!=null&&!o.reviewRequired()&&Set.of("PAID_WAITING_A","PAID_WAITING_TEAM","GROUP_COMPLETED").contains(o.businessStatus())&&p!=null&&!Boolean.TRUE.equals(p.get("review_required"))&&"SUCCEEDED".equals(p.get("funds_state"))&&"ACCEPTED".equals(p.get("a_acceptance"));}
 public FulfillmentWork claim(String id){return tx.execute(s->{var before=first("SELECT * FROM b_trade_work WHERE work_id=? AND kind='TEAM_COMPLETED'",id);if(before==null)return null;var o=lock((String)before.get("order_id"));var p=o==null?null:first("SELECT * FROM b_payment WHERE order_id=?",o.orderId());var out=p==null?null:first("SELECT * FROM b_trade_outbox WHERE payment_id=? AND event_type='PAYMENT_SUCCEEDED' FOR UPDATE",p.get("payment_id"));var e=tree(raw(before,"evidence"));cursor(e);var w=first("SELECT * FROM b_trade_work WHERE work_id=? FOR UPDATE",id);long n=now();if(!Set.of("READY","WAITING_DEPENDENCY","LEASED").contains(w.get("state"))||((Number)w.get("next_attempt_ms")).longValue()>n||w.get("lease_until_ms")!=null&&((Number)w.get("lease_until_ms")).longValue()>n)return null;
  if(!ready(o,p)||out==null){waitFor(w,n);return null;}String token=UUID.randomUUID().toString();one(db.update("UPDATE b_trade_work SET state='LEASED',lease_token=?,lease_until_ms=?,next_attempt_ms=?,updated_at_ms=? WHERE work_id=?",token,n+30000,n+30000,n,id));return new FulfillmentWork(id,o.orderId(),o.confirmation().userId(),token,((Number)w.get("intent_version")).longValue(),new TradeDelivery(out.get("event_id").toString(),p.get("payment_id").toString(),o.orderId(),o.confirmation().userId(),raw(out,"body"),out.get("body_hash").toString(),out.get("state").toString(),0,token));
 });}
 private boolean current(Map<String,Object> w,FulfillmentWork t,long n){return w!=null&&"LEASED".equals(w.get("state"))&&t.token().equals(w.get("lease_token"))&&t.intentVersion()==((Number)w.get("intent_version")).longValue()&&((Number)w.get("lease_until_ms")).longValue()>n;}
 private void conflict(Map<String,Object> w,Map<String,Object> p,String body,long n){settlement.quarantine(w.get("work_id").toString(),"TEAM","FULFILLMENT",null,null,body.getBytes(StandardCharsets.UTF_8),"FULFILLMENT_EVIDENCE_CONFLICT");db.update("UPDATE b_trade_work SET state='REVIEW_REQUIRED',alerted=TRUE,lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE work_id=?",n,w.get("work_id"));db.update("UPDATE b_market_order SET review_required=TRUE,last_error='FULFILLMENT_EVIDENCE_CONFLICT',order_version=order_version+1,updated_at_ms=? WHERE order_id=?",n,w.get("order_id"));if(p!=null)db.update("UPDATE b_payment SET review_required=TRUE,last_error='FULFILLMENT_EVIDENCE_CONFLICT',version=version+1,updated_at_ms=? WHERE payment_id=?",n,p.get("payment_id"));}
 public void complete(FulfillmentWork t,TradeReceipt receipt){tx.executeWithoutResult(s->{var o=lock(t.orderId());var p=first("SELECT * FROM b_payment WHERE order_id=?",t.orderId());db.queryForList("SELECT event_id FROM b_trade_outbox WHERE payment_id=? AND event_type='PAYMENT_SUCCEEDED' ORDER BY event_id FOR UPDATE",t.payment().paymentId());var before=first("SELECT * FROM b_trade_work WHERE work_id=?",t.id());var e=tree(raw(before,"evidence"));var c=cursor(e);var w=first("SELECT * FROM b_trade_work WHERE work_id=? FOR UPDATE",t.id());long n=now();if(!current(w,t,n))return;if(!ready(o,p)||receipt==null){waitFor(w,n);return;}
  String proof=receipt.body();CompletionEvidence evidence;ReservationEvidence updatedA;JsonNode result;try{
   if(!OrderService.hash(raw(w,"evidence")).equals(w.get("evidence_hash"))||!OrderService.hash(proof).equals(receipt.hash()))throw new IllegalArgumentException();TradeMessageReader.validateTeam("TEAM_COMPLETED",e.get("payload"));if(!TradeMessageReader.roster(e.get("payload"),"outTradeNoList").contains(o.orderId())||!o.confirmation().source().equals(e.path("source").asText())||!o.confirmation().channel().equals(e.path("channel").asText())||!o.evidence().teamId().equals(e.path("payload").path("teamId").asText())||!o.evidence().activityId().equals(e.path("payload").path("activityId").asText())||c==null||Boolean.TRUE.equals(c.get("review_required"))||!"TEAM_COMPLETED".equals(c.get("status")))throw new IllegalArgumentException();
   var latest=tree(raw(c,"body"));TradeMessageReader.validateTeam("TEAM_COMPLETED",latest.get("payload"));if(!canonicalHash(Map.of("type","TEAM_COMPLETED","payload",latest.get("payload"))).equals(c.get("fact_hash"))||!latest.path("source").asText().equals(e.path("source").asText())||!latest.path("channel").asText().equals(e.path("channel").asText())||!latest.path("payload").path("teamId").asText().equals(o.evidence().teamId())||ReservationEvidence.version(latest.path("payload").path("teamVersion").asText())!=((Number)c.get("team_version")).longValue())throw new IllegalArgumentException();if(!TradeMessageReader.roster(latest.get("payload"),"outTradeNoList").contains(o.orderId())||!latest.path("payload").path("activityId").asText().equals(o.evidence().activityId()))throw new IllegalArgumentException();var env=tree(proof);var payload=env.get("payload");TradeMessageReader.validateResult(payload);if(!t.payment().eventId().equals(receipt.originalEventId())||!t.payment().eventId().equals(payload.path("originalEventId").asText())||!o.confirmation().source().equals(env.path("source").asText())||!o.confirmation().channel().equals(env.path("channel").asText())||!Set.of("APPLIED","IGNORED").contains(payload.path("outcome").asText()))throw new IllegalArgumentException();result=payload.get("result");var money=result.get("payment");evidence=new CompletionEvidence(result.path("orderId").asText(),result.path("outTradeNo").asText(),result.path("teamId").asText(),result.path("orderStatus").asText(),result.path("teamStatus").asText(),result.path("recordVersion").asText(),result.path("teamVersion").asText(),money.path("paymentId").asText(),money.path("paidAmount").asText(),money.path("currency").asText(),money.path("paidAt").asText());
   var local=new Payment(p.get("payment_id").toString(),o.orderId(),t.userId(),((Number)p.get("version")).longValue(),p.get("funds_state").toString(),p.get("gate").toString(),p.get("a_acceptance").toString(),p.get("amount").toString(),p.get("currency").toString(),((Number)p.get("payment_deadline_ms")).longValue(),((Number)p.get("paid_at_ms")).longValue(),(String)p.get("active_attempt_id"),(String)p.get("success_attempt_id"),false,null);evidence.validate(o,local);if(!OrderService.hash(raw(p,"success_fact")).equals(p.get("success_hash")))throw new IllegalArgumentException();
   long version=ReservationEvidence.version(evidence.teamVersion());if(version<((Number)c.get("team_version")).longValue()||ReservationEvidence.version(evidence.recordVersion())<ReservationEvidence.version(o.evidence().recordVersion())){waitFor(w,n);return;}if(!"COMPLETED".equals(evidence.teamStatus()))throw new IllegalArgumentException();var fields=json.convertValue(o.evidence(),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});fields.put("orderStatus","PAID");fields.put("paymentPresent",true);fields.put("teamStatus","COMPLETED");fields.put("recordVersion",evidence.recordVersion());fields.put("teamVersion",evidence.teamVersion());updatedA=json.convertValue(fields,ReservationEvidence.class);updatedA.validate(o);
  }catch(IllegalArgumentException | cn.zj.zjmarket.types.exception.SyncTransportFailure | NullPointerException invalid){conflict(w,p,proof,n);return;}
  var reservation=first("SELECT * FROM b_inventory_reservation WHERE order_id=?",o.orderId());var existing=first("SELECT * FROM b_fulfillment WHERE order_id=? FOR UPDATE",o.orderId());
  if(existing!=null){if(!"GROUP_COMPLETED".equals(o.businessStatus())||!"PENDING".equals(existing.get("status"))||!o.evidence().teamId().equals(existing.get("team_id"))||db.queryForObject("SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='CONFIRM'",Long.class,o.orderId())!=1||!"CONFIRMED".equals(reservation.get("state"))||!t.payment().paymentId().equals(existing.get("payment_id"))||!OrderService.hash(raw(existing,"snapshot")).equals(existing.get("snapshot_hash"))){conflict(w,p,proof,n);return;}done(w,n);return;}
  if(!"HELD".equals(reservation.get("state"))||!o.orderId().equals(first("SELECT active_order_id FROM b_purchase_guard WHERE user_id=? AND goods_id=?",t.userId(),o.confirmation().conditions().goodsId()).get("active_order_id"))){conflict(w,p,proof,n);return;}
  var row=first("SELECT * FROM b_inventory_account WHERE goods_id=?",o.confirmation().conditions().goodsId());var old=new InventoryAccount(row.get("goods_id").toString(),((Number)row.get("available")).longValue(),((Number)row.get("reserved")).longValue(),((Number)row.get("sold")).longValue(),((Number)row.get("inventory_version")).longValue(),((Number)row.get("updated_at_ms")).longValue());InventoryAccount after;try{after=old.confirm(1,n);}catch(IllegalArgumentException | cn.zj.zjmarket.types.exception.SyncTransportFailure | NullPointerException invalid){conflict(w,p,proof,n);return;}
  one(db.update("UPDATE b_inventory_account SET reserved=?,sold=?,inventory_version=?,updated_at_ms=? WHERE goods_id=? AND inventory_version=?",after.reserved(),after.sold(),after.version(),n,after.goodsId(),old.version()));one(db.update("UPDATE b_inventory_reservation SET state='CONFIRMED',resolved_at_ms=?,resolution_basis='TEAM_COMPLETED' WHERE order_id=? AND state='HELD'",n,o.orderId()));
  one(db.update("INSERT INTO b_inventory_ledger(ledger_id,goods_id,kind,order_id,business_key,delta_available,before_available,after_available,before_reserved,after_reserved,before_sold,after_sold,reason,created_at_ms) VALUES(?,?,'CONFIRM',?,?,0,?,?,?,?,?,?,'TEAM_COMPLETED',?)",UUID.randomUUID().toString(),after.goodsId(),o.orderId(),o.orderId(),old.available(),after.available(),old.reserved(),after.reserved(),old.sold(),after.sold(),n));
  String snapshot=encode(Map.of("order",o,"paymentId",t.payment().paymentId(),"successHash",p.get("success_hash"),"teamEvent",e,"latestTeam",tree(raw(c,"body")),"tradeQuery",tree(proof),"before",old,"after",after));one(db.update("INSERT INTO b_fulfillment(order_id,payment_id,user_id,goods_id,team_id,team_version,snapshot,snapshot_hash,confirmed_at_ms) VALUES(?,?,?,?,?,?,?,?,?)",o.orderId(),t.payment().paymentId(),t.userId(),after.goodsId(),o.evidence().teamId(),ReservationEvidence.version(evidence.teamVersion()),snapshot.getBytes(StandardCharsets.UTF_8),OrderService.hash(snapshot),n));
  String a=encode(updatedA);one(db.update("UPDATE b_market_order SET business_status='GROUP_COMPLETED',a_evidence=?,a_evidence_hash=?,order_version=order_version+1,updated_at_ms=? WHERE order_id=?",a,OrderService.hash(a),n,o.orderId()));one(db.update("UPDATE b_purchase_guard SET active_order_id=NULL,updated_at_ms=? WHERE user_id=? AND goods_id=? AND active_order_id=?",n,t.userId(),after.goodsId(),o.orderId()));done(w,n);
 });}
 private void done(Map<String,Object> w,long n){one(db.update("UPDATE b_trade_work SET state='DONE',lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE work_id=?",n,w.get("work_id")));}
 public void retry(FulfillmentWork t){tx.executeWithoutResult(s->{var o=lock(t.orderId());var w=first("SELECT * FROM b_trade_work WHERE work_id=? FOR UPDATE",t.id());long n=now();if(!current(w,t,n))return;int fail=((Number)w.get("failure_count")).intValue()+1;db.update("UPDATE b_trade_work SET state='WAITING_DEPENDENCY',failure_count=?,alerted=alerted OR ?>=5,next_attempt_ms=?,lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE work_id=?",fail,fail,n+Math.min(30000L,2000L*(1L<<Math.min(4,fail-1))),n,t.id());});}
 public Map<String,Object> summary(String user,String order){var row=first("SELECT f.* FROM b_fulfillment f JOIN b_market_order o ON o.order_id=f.order_id WHERE f.order_id=? AND o.user_id=?",order,user);if(row==null)return null;return Map.of("status",row.get("status"),"confirmedAt",PaymentService.time(((Number)row.get("confirmed_at_ms")).longValue()),"paymentId",row.get("payment_id"),"teamId",row.get("team_id"));}
}
